(function(scope){
const tuning=[40,45,50,55,59,64];
// Five connected, two-notes-per-string boxes, relative to the minor tonic on string 6.
const boxes=[[[0,3],[0,2],[0,2],[0,2],[0,3],[0,3]],[[3,5],[2,5],[2,5],[2,4],[3,5],[3,5]],[[5,7],[5,7],[5,7],[4,7],[5,8],[5,7]],[[7,10],[7,10],[7,9],[7,9],[8,10],[7,10]],[[10,12],[10,12],[9,12],[9,12],[10,12],[10,12]]];
function pentatonic(field){return(field.mode==='major'?[0,1,2,4,5]:[0,2,3,4,6]).map(i=>field.notes[i]);}
function positions(field){const minorRoot=Music.pc(field.notes[field.mode==='major'?5:0]);const anchor=(minorRoot-4+12)%12;return boxes.map(box=>{let frets=box.map(row=>row.map(n=>n+anchor));const shift=Math.floor(Math.min(...frets.flat())/12)*12;frets=frets.map(row=>row.map(n=>n-shift));return frets;}).sort((a,b)=>Math.min(...a.flat())-Math.min(...b.flat())).map((frets,i)=>({number:i+1,frets,occurrences:[-12,0,12,24].map(shift=>{const raw=frets.map(row=>row.map(n=>n+shift));const visible=raw.map(row=>row.filter(n=>n>=0&&n<=24));const all=visible.flat();return{frets:visible,min:Math.min(...all),max:Math.max(...all),partial:all.length<12};}).filter(p=>p.frets.flat().length>=4)}));}
function noteAt(notes,string,fret){return notes.find(n=>Music.pc(n)===(tuning[string]+fret)%12);}
function neck(notes,root,start=0,end=24,frets=null){const full=!frets,step=full?48:42,left=45,width=left+(end-start+1)*step+18,height=220;const title=`${Music.pretty(root)}: casas ${start} a ${end}. Mi aguda em cima, Mi grave embaixo.`;let svg=`<svg class="scale-neck ${full?'full-neck':'box-neck'}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${title}"><title>${title}</title>`;const center=f=>left+(f-start+.5)*step;for(let f=start;f<=end;f++){svg+=`<text x="${center(f)}" y="19" class="neck-fret">${f}</text>`;if(f>0)svg+=`<line x1="${left+(f-start)*step}" x2="${left+(f-start)*step}" y1="38" y2="183" class="neck-wire"/>`;if([3,5,7,9,12,15,17,19,21,24].includes(f))svg+=`<text x="${center(f)}" y="212" class="neck-marker">${f%12===0?'••':'•'}</text>`;}if(start<=1)svg+=`<line x1="${left+(1-start)*step}" x2="${left+(1-start)*step}" y1="38" y2="183" class="neck-nut"/>`;for(let s=0;s<6;s++){const y=38+(5-s)*29;svg+=`<text x="17" y="${y+4}" class="neck-string-label">${['E','A','D','G','B','e'][s]}</text><line x1="${left}" x2="${width-18}" y1="${y}" y2="${y}" class="neck-string" style="stroke-width:${.8+(5-s)*.15}"/>`;for(let f=start;f<=end;f++){const n=noteAt(notes,s,f);if(!n||(frets&&!frets[s].includes(f)))continue;const tonic=Music.pc(n)===Music.pc(root);svg+=`<g><title>${s===5?'1ª':6-s+'ª'} corda, ${f===0?'solta':'casa '+f}: ${Music.pretty(n)}${tonic?', tônica':''}</title><circle cx="${center(f)}" cy="${y}" r="14" class="${tonic?'neck-root':'neck-note'}"/><text x="${center(f)}" y="${y+4}" class="neck-note-label ${tonic?'root-label':''}">${Music.pretty(n)}</text></g>`;}}return svg+'</svg>';}
function pentSection(field,relative=false){const notes=pentatonic(field),label=Music.full(field.key)+(field.mode==='major'?' maior':' menor'),shapes=positions(field);return `<section id="${relative?'pent-relative':'pent-main'}" class="pent-section ${relative?'relative-pent':''}"><div class="section-top"><div><p class="eyebrow">${relative?'PENTATÔNICA DO TOM RELATIVO':'PENTATÔNICA DO TOM ESCOLHIDO'}</p><h2>${label}</h2></div><span class="pill">5 shapes · 24 casas</span></div><div class="scale-note-list">${notes.map((n,i)=>`<span class="${i===0?'root-pill':''}">${Music.pretty(n)}</span>`).join('')}<small>Graus ${field.mode==='major'?'1 · 2 · 3 · 5 · 6':'1 · ♭3 · 4 · 5 · ♭7'}</small></div><div class="neck-scroll" tabindex="0" aria-label="Braço completo da pentatônica de ${label}; role horizontalmente">${neck(notes,field.key)}</div><div class="shape-grid">${shapes.map(p=>`<article class="shape-card"><h3>Shape ${p.number}</h3>${p.occurrences.map(o=>`<div class="shape-occurrence"><p>Casas ${o.min}–${o.max}${o.partial?' <span>trecho</span>':''}</p>${neck(notes,field.key,o.min,o.max,o.frets)}</div>`).join('')}</article>`).join('')}</div></section>`;}
let lastKey='';function render(field){const key=field.key+'/'+field.mode;if(lastKey===key)return;lastKey=key;const relative=Music.field(field.notes[field.mode==='major'?5:2],field.mode==='major'?'minor':'major');const label=Music.full(field.key)+(field.mode==='major'?' maior':' menor natural');document.getElementById('fretboard-scales').innerHTML=`<div class="section-top"><div><p class="eyebrow">ESCALAS NO BRAÇO</p><h2>Explore cada região do violão</h2></div><span class="pill">E A D G B e</span></div><p class="neck-intro">Leia os desenhos com a corda mais aguda em cima e a mais grave embaixo. Os números acima são as casas; 0 indica corda solta.</p><p class="neck-legend"><span class="root-key"></span> Tônica <span class="note-key"></span> Outras notas da escala <span class="scroll-hint">Deslize o braço para ver até a casa 24 →</span></p><section class="diatonic-section"><h3>Escala de ${label}</h3><p class="neck-subtitle">${field.notes.map(Music.pretty).join(' · ')} · Todas as 7 notas, da corda solta à casa 24.</p><div class="neck-scroll" tabindex="0" aria-label="Escala completa de ${label}; role horizontalmente">${neck(field.notes,field.key)}</div></section>${pentSection(field)}<p class="relative-explanation">${Music.full(field.key)} ${field.mode==='major'?'maior':'menor'} e ${Music.full(relative.key)} ${relative.mode==='major'?'maior':'menor'} são relativos: suas pentatônicas têm as mesmas cinco notas e ocupam as mesmas casas. O destaque da tônica muda para mostrar o centro de cada tom.</p>${pentSection(relative,true)}<p class="neck-footnote">Os cinco shapes estão numerados pela ordem em que aparecem neste braço, das casas mais baixas às mais altas. Os desenhos se repetem a cada 12 casas. “Trecho” indica um shape cortado pelo início ou pelo fim do braço mostrado.</p>`;}
scope.Scales={pentatonic,positions,noteAt,neck,render};if(typeof module!=='undefined')module.exports=scope.Scales;
})(typeof window!=='undefined'?window:globalThis);
